window.DIGEST.foryou.push(...[{"id": "2112551437314183171", "url": "https://x.com/AskVenice/status/2112551437314183171", "text": "In Venice Chat: DeepSeek V4.1 Flash.\n\nPick it in the model menu, drop in your sensitive files, and ask. Ten receipts. One expense table. $934.50.\n\nIt runs privately. Nothing you send is stored.", "name": "Venice", "handle": "AskVenice", "avatar": "https://pbs.twimg.com/profile_images/2063006544615120896/yzx4UbK7_200x200.png", "likes": 140, "rts": 11, "replies": 13, "views": 9339, "ts": 1792506486, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112551413259931648/vid/avc1/1280x720/iiuGqUlWrx0VRn8K.mp4?tag=16", "hd": "https://video.twimg.com/amplify_video/2112551413259931648/vid/avc1/1920x1080/mFAWrL68jJjjRR2y.mp4?tag=16", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112551413259931648/img/sU6KY6qxGS9aN23O.jpg", "dur": 30}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 5.66, "thread": [], "tier": "worth"}, {"id": "2112638484267819285", "url": "https://x.com/BSCNews/status/2112638484267819285", "text": "Ondo Finance tokenized stocks land on Jumper across four chains\n\nMore than 450 tokenized US stocks and ETFs from @Ondo are now live on @jumperapp, the cross-chain trading app launched by @lifiprotocol. Users can access them on Ethereum, Solana, BNB Chain, and HyperEVM.\n\nEach token is backed by real shares held with US-registered broker-dealers. LIFI first opened Ondo’s stocks to its partner apps in June.", "name": "BSCN", "handle": "BSCNews", "avatar": "https://pbs.twimg.com/profile_images/1740337106512187392/o0KBpMEp_200x200.jpg", "likes": 94, "rts": 12, "replies": 10, "views": 9851, "ts": 1792527240, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112617005111029760/vid/avc1/1220x720/aFcI_Lr7EyYizN-V.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112617005111029760/vid/avc1/2000x1180/VHioaK7QdrF3A6br.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112617005111029760/img/YkuNUiI8zYwKpI36.jpg", "dur": 15}], "quote": null, "reply_to": null, "cat": "AI Tools & Agents", "score": 5.66, "thread": [], "tier": "worth"}, {"id": "2112707809406063089", "url": "https://x.com/chesny/status/2112707809406063089", "text": "NOBODY talks about Hongyang Zhang and it's kind of wild\n\nhim and the SafeAI Lab team at Waterloo put out three EAGLE papers in under two years. ICML 2024, EMNLP 2024, NeurIPS 2025\n\nearlier versions ended up inside vLLM, SGLang and TensorRT-LLM, so if you run open models there's a decent chance you've used their work without knowing the name\n\nEAGLE-4 is on github now and the idea changed a bit. instead of one fixed setup it adapts to your batch size and your hardware\n\nanyone here already running EAGLE-3 in prod? curious if it was worth it", "name": "Chesny", "handle": "chesny", "avatar": "https://pbs.twimg.com/profile_images/2094133897483243520/x9t2-kSv_200x200.jpg", "likes": 75, "rts": 10, "replies": 8, "views": 868, "ts": 1792543768, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVHYjFuX0AA-ddX.jpg?name=orig"}], "quote": {"id": "2112660683670323531", "url": "https://x.com/EagleCorp/status/2112660683670323531", "text": "EAGLE-4 is here.\n\nFrom EAGLE-1 to EAGLE-3, we’ve kept making inference faster. \n\nEAGLE-4 is our fastest yet.\n\n961.6 tokens/s on @Alibaba_Qwen’s Qwen3.8-27B with TokenSpeed (BF16, 4× @NVIDIA B300, TP4, one request, T=0).\n\nGithub: https://github.com/eagle-hq/EAGLE-4", "name": "Eagle", "handle": "EagleCorp", "avatar": "https://pbs.twimg.com/profile_images/2057212553915248640/zgJtC7pK_200x200.jpg", "likes": 4174, "rts": 519, "replies": 376, "views": 1080426, "ts": 1792532532, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112660579664187392/vid/avc1/1280x720/-10uYli5CGPejFwB.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112660579664187392/vid/avc1/1920x1080/6UlvgUxk_hy6qXRU.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112660579664187392/img/oFNlAedcp82x1A_3.jpg", "dur": 74}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.66, "thread": [], "tier": "worth"}, {"id": "2112581637728850136", "url": "https://x.com/dravenip/status/2112581637728850136", "text": "quick math for anyone editing images at volume:\n\n> 1,000 edits.\n> $135 and ~7.4 hours on nano banana pro.\n> $60 and ~2.2 hours on krea 3.\n\nsame edits. less than half the cost. 5 hours back.\n\nand it’s not trading quality for speed: krea 3 just ranked top 4 on the image arenas, only behind openai, and it’s the only company in the top 10 valued under $1T.\n\nthe part that actually changes how you work: when an edit takes 8 seconds instead of 30, you stop settling for the first result. you try ten versions and keep the best one.\n\nwhat would you edit if it took 8 seconds?", "name": "draven", "handle": "dravenip", "avatar": "https://pbs.twimg.com/profile_images/2094585676800860160/6Xm8L9f6_200x200.jpg", "likes": 143, "rts": 7, "replies": 9, "views": 16041, "ts": 1792513686, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112581266788728832/vid/avc1/1280x720/zLQZ_Kd61--pUwg_.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112581266788728832/vid/avc1/3840x2160/u3zLjOm_7soZkptf.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112581266788728832/img/4qNaTA-ou2pp33kp.jpg", "dur": 7}], "quote": {"id": "2112567020353102324", "url": "https://x.com/krea_ai/status/2112567020353102324", "text": "today, Krea 3 makes it to the top of image arenas.\n\n- \"Fast\" pushes the pareto curve of speed and quality.\n- \"Ultra\" ranks top-4, only surpassed by OpenAI models.\n\nthe only company valued under $1T in the top-10!\n\nmore below 👇", "name": "Krea", "handle": "krea_ai", "avatar": "https://pbs.twimg.com/profile_images/2052148578588753920/deUXA7cZ_200x200.jpg", "likes": 1097, "rts": 143, "replies": 103, "views": 911636, "ts": 1792510201, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112560706319261696/vid/avc1/1280x720/I09XfdJSlPHN1GRN.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112560706319261696/vid/avc1/1920x1080/dNLTktxkBQvdw6CQ.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112560706319261696/img/adh7bZDj88TDFAP8.jpg", "dur": 35}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.66, "thread": [], "tier": "worth"}, {"id": "2112655619052257562", "url": "https://x.com/viridiancolors/status/2112655619052257562", "text": "please look at this look how happy this cat is to get a green bean oh my gosh", "name": "viridian", "handle": "viridiancolors", "avatar": "https://pbs.twimg.com/profile_images/2109239981940125696/1RWSeQNi_200x200.jpg", "likes": 19017, "rts": 1259, "replies": 24, "views": 352444, "ts": 1792531325, "media": [], "quote": {"id": "2111787628710314044", "url": "https://x.com/populicc/status/2111787628710314044", "text": "Yeşil fasulyeyi çok seven bir sarman:", "name": "Populicc", "handle": "populicc", "avatar": "https://pbs.twimg.com/profile_images/1876726293087088640/fOx3keSl_200x200.jpg", "likes": 8105, "rts": 781, "replies": 16, "views": 856074, "ts": 1792324380, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2111787406735138816/vid/avc1/720x900/2r87sQgKi-uuoUe1.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2111787406735138816/vid/avc1/1536x1920/CzSNOuVgCzXfzLDM.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2111787406735138816/img/FqAK0OOeCFQd9___.jpg", "dur": 17}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "Everything Else", "score": 5.66, "thread": [], "tier": "worth"}, {"id": "2112681311106466010", "url": "https://x.com/teslaownersSV/status/2112681311106466010", "text": "Elon Musk says SpaceX is aiming for the first Starship launch from Starbase Louisiana in 2028, a year ahead of the 2029 target. \"I think we'll be at scale, launching from Louisiana at scale in 29. I'm highly confident.\"", "name": "Tesla Owners Silicon Valley", "handle": "teslaownersSV", "avatar": "https://pbs.twimg.com/profile_images/2089050162710929408/Xy5O8i3g_200x200.jpg", "likes": 76, "rts": 11, "replies": 11, "views": 22675, "ts": 1792537450, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112680932658577408/vid/avc1/640x360/Q1IofukOYbQvp3px.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112680932658577408/vid/avc1/1280x720/Dsuk9aVUjACThcjR.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112680932658577408/img/VLs991uGZVgjpeTh.jpg", "dur": 25}], "quote": null, "reply_to": null, "cat": "AI Tools & Agents", "score": 5.66, "thread": [], "tier": "worth"}, {"id": "2112587873526636616", "url": "https://x.com/Parsats_eth/status/2112587873526636616", "text": "Vyb works the way design files already work, in layers\n\nYou tell it where each piece goes, it places your real logo as supplied and you can edit any single element later", "name": "PARSA", "handle": "Parsats_eth", "avatar": "https://pbs.twimg.com/profile_images/2064754130149625856/uzulyDhp_200x200.jpg", "likes": 122, "rts": 2, "replies": 23, "views": 10900, "ts": 1792515173, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112587750884929536/vid/avc1/1280x720/HBfvxKAF_vsyYANK.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112587750884929536/vid/avc1/1920x1080/GfUtfvwjja3ksrCq.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112587750884929536/img/1yDP5U6P6fGp6i8N.jpg", "dur": 32}], "quote": {"id": "2112581900779012503", "url": "https://x.com/anurahk/status/2112581900779012503", "text": "I launched the first image and video generation models at Google, and kept asking why all AI designs look the same.\n\nAI has brought us the WORST era of design. \n\nIt made content creation effortless, but it also made 90% of it look painfully generic.\n\nMy co-founder and I spent 2 years building in stealth to change that.\n\nMeet Vyb, the first AI design model that understands your taste like a designer would.\n\nRT + comment your website URL and we’ll make your first design.", "name": "Anusha Ramesh", "handle": "anurahk", "avatar": "https://pbs.twimg.com/profile_images/2083966148123693056/exmPXdbp_200x200.jpg", "likes": 1298, "rts": 171, "replies": 214, "views": 1822098, "ts": 1792513749, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112576977475633152/vid/avc1/1280x720/61WcbZ_4wRzGashG.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112576977475633152/vid/avc1/3840x2160/9sM5IjuklsVkv5hw.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112576977475633152/img/kNLFFHqyStT3ddJQ.jpg", "dur": 84}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.65, "thread": [], "tier": "worth"}, {"id": "2112613288408404166", "url": "https://x.com/HermesWatcher/status/2112613288408404166", "text": "The Hermes plugin catalog is getting ridiculous.\n\nHermes basically has an app store now, and it's growing faster than anyone can scroll it.\n\nThere are over 700 plugins, with new ones landing nearly every day. A few things Hermes can do with a single install:\n\n▸ Drive a real phone\n▸ Search and book real flights and hotels\n▸ Talk to you through a tiny ESP32 gadget\n▸ Work inside Blender and TouchDesigner\n▸ Run your smart home through Home Assistant\n▸ Chat with you in your X DMs\n▸ Call you on WhatsApp\n\nEvery listing is reviewed by the Hermes maintainers and pinned to an exact version, so what you install is what got checked.\n\nMore and more of what Hermes can do is showing up here first.", "name": "Hermes Release Watch", "handle": "HermesWatcher", "avatar": "https://pbs.twimg.com/profile_images/2079058210410094592/t-ZASzl0_200x200.jpg", "likes": 116, "rts": 10, "replies": 7, "views": 10391, "ts": 1792521233, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112613256531693568/vid/avc1/1280x720/VKBT4OsqLbLjSpir.mp4?tag=16", "hd": "https://video.twimg.com/amplify_video/2112613256531693568/vid/avc1/1920x1080/K2kGT_m2PLTLty3u.mp4?tag=16", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112613256531693568/img/oH3hLljiYLzk-gAL.jpg", "dur": 27}], "quote": null, "reply_to": null, "cat": "AI Tools & Agents", "score": 5.65, "thread": [], "tier": "worth"}, {"id": "2112525171537977425", "url": "https://x.com/HochreiterSepp/status/2112525171537977425", "text": "KronLSTM is out!\nKronLSTM uses the Kronecker Delta Rule for minimally invasive memory revisions compared with delta-rule. We proof that the expected norm of the memory matrix is uniformly bounded. KronLSTM is particularly well suited for long-context language modeling. So Proud!", "name": "Sepp Hochreiter", "handle": "HochreiterSepp", "avatar": "https://pbs.twimg.com/profile_images/1463121437196267522/lT6EWJED_200x200.jpg", "likes": 137, "rts": 22, "replies": 3, "views": 4562, "ts": 1792500224, "media": [], "quote": {"id": "2112499069373530145", "url": "https://x.com/anamariarp17/status/2112499069373530145", "text": "New paper 🧵 KronLSTM: a new member of the xLSTM family, built on the Kronecker Delta Rule.\n✏️ less interference than delta-rule updates\n📏 provably bounded memory, no normalizer state\n📈 competitive with, often ahead of, (Gated) DeltaNet, especially at long context", "name": "Anamaria-Roberta Hartl", "handle": "anamariarp17", "avatar": "https://pbs.twimg.com/profile_images/2091627027237416960/3EQtY49A_200x200.jpg", "likes": 115, "rts": 27, "replies": 3, "views": 8847, "ts": 1792494001, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112404561348464640/vid/avc1/640x360/dHIh9VfN9RsFEzyG.mp4?tag=14", "hd": "https://video.twimg.com/amplify_video/2112404561348464640/vid/avc1/640x360/dHIh9VfN9RsFEzyG.mp4?tag=14", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112404561348464640/img/wXLDDE1jlIZJd6Be.jpg", "dur": 10}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "Research & Safety", "score": 5.65, "thread": [], "tier": "worth"}, {"id": "2112592448900010112", "url": "https://x.com/abxxai/status/2112592448900010112", "text": "Vyb from Coco Labs is out of stealth!\n\nhere are 5 things to know:\n\n1) it builds designs, not images\n\n2) it starts from your website, pulling in your logo, fonts and exact colors\n\n3) your product photos are placed as they are, never redrawn\n\n4) every element is its own layer, so you can edit one piece\n\n5) layers export to Figma so you can keep going\n\nit's private beta for now. the layers are what got me", "name": "Abdul Shakoor", "handle": "abxxai", "avatar": "https://pbs.twimg.com/profile_images/2095534540525903873/q3A8G-dZ_200x200.jpg", "likes": 125, "rts": 9, "replies": 10, "views": 18493, "ts": 1792516264, "media": [], "quote": {"id": "2112581900779012503", "url": "https://x.com/anurahk/status/2112581900779012503", "text": "I launched the first image and video generation models at Google, and kept asking why all AI designs look the same.\n\nAI has brought us the WORST era of design. \n\nIt made content creation effortless, but it also made 90% of it look painfully generic.\n\nMy co-founder and I spent 2 years building in stealth to change that.\n\nMeet Vyb, the first AI design model that understands your taste like a designer would.\n\nRT + comment your website URL and we’ll make your first design.", "name": "Anusha Ramesh", "handle": "anurahk", "avatar": "https://pbs.twimg.com/profile_images/2083966148123693056/exmPXdbp_200x200.jpg", "likes": 1298, "rts": 171, "replies": 214, "views": 1822098, "ts": 1792513749, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112576977475633152/vid/avc1/1280x720/61WcbZ_4wRzGashG.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112576977475633152/vid/avc1/3840x2160/9sM5IjuklsVkv5hw.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112576977475633152/img/kNLFFHqyStT3ddJQ.jpg", "dur": 84}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.65, "thread": [], "tier": "worth"}, {"id": "2112563016185323878", "url": "https://x.com/tripoai/status/2112563016185323878", "text": "EdenLive, a real-time generative renderer, is now open-sourced by @VASTAIResearch.\n\nIt transforms 3D blockouts, game engine footage, 2D cartoons, and real-world video into detailed photorealistic or stylized video.\n\n24+ FPS at 720p. A 5B model on a single RTX 5090.", "name": "Tripo", "handle": "tripoai", "avatar": "https://pbs.twimg.com/profile_images/1767828642678374400/0moo4B0D_200x200.jpg", "likes": 113, "rts": 21, "replies": 5, "views": 10292, "ts": 1792509247, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112562698076692480/vid/avc1/1280x720/LeD16WLrtLaxUS5z.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112562698076692480/vid/avc1/3840x2160/7ycwq3Scd2mgosjr.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112562698076692480/img/cNpwZcrf5W7DEAye.jpg", "dur": 147}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 5.65, "thread": [], "tier": "worth"}, {"id": "2112589514795598131", "url": "https://x.com/marcusyul/status/2112589514795598131", "text": "AN EX-APPLE PM JUST LAUNCHED HER OWN HEALTH AGENT\n\nPraneeta Pujari:\n→ 6 years on Apple Watch\n→ Lives with migraines\n→ Cares for her mum\n\nShe's spent over 10 years managing her mum's chronic pain, and that's where Niq comes from.\n\nAn agent that connects your watch, your records and your labs to look for signs of a migraine flare before it hits.\n\nAnd it doesn't stop at alerts:\n→ Books the appointment\n→ Sorts the prescription\n→ Handles the insurance\n→ Delivers your meds\n\nWith real doctors behind it.", "name": "marcus", "handle": "marcusyul", "avatar": "https://pbs.twimg.com/profile_images/2111849261096718336/9rC8a9xw_200x200.jpg", "likes": 89, "rts": 17, "replies": 16, "views": 37023, "ts": 1792515564, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112589443962159104/vid/avc1/1502x720/Dm_9712yR9yX67Ag.mp4?tag=16", "hd": "https://video.twimg.com/amplify_video/2112589443962159104/vid/avc1/2254x1080/VEv-pJ7ysXK-XP8M.mp4?tag=16", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112589443962159104/img/uskG2eLjEGZ_BX2y.jpg", "dur": 19}], "quote": {"id": "2112580659558682684", "url": "https://x.com/PraneetaPujari/status/2112580659558682684", "text": "I left @Apple to build healthcare that listens and acts early. Today, I'm excited to introduce UniqueHuman.\n\nWe're building proactive healthcare agents that handle every step of care for people with chronic conditions.\n\nOur mission is to end chronic suffering. Today, we begin with migraines.", "name": "Praneeta Pujari", "handle": "PraneetaPujari", "avatar": "https://pbs.twimg.com/profile_images/2100108822937489408/4DySfLTn_200x200.jpg", "likes": 2340, "rts": 425, "replies": 189, "views": 547190, "ts": 1792513453, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112575253000196096/vid/avc1/1280x720/gbcA8-FVzdsnlhFj.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112575253000196096/vid/avc1/1920x1080/R6bNlZuATn4YIT4_.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112575253000196096/img/9O1ngN28s0lh4Gu-.jpg", "dur": 129}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Tools & Agents", "score": 5.65, "thread": [], "tier": "worth"}, {"id": "2112763337419186651", "url": "https://x.com/0xdnll/status/2112763337419186651", "text": "everyone is building for the agent economy to work. but what happens when two agents disagree?\n\nin genesis episode 5, albert castellana points out that payments, identity and discovery are being built for the happy path. internet court is built for the other side of that equation, giving agents a way to settle disputes. metamask, near, okx and bnb chain are among the names already involved.\n\nto me, an economy needs more than a way to make deals. it needs a way to resolve them when things go wrong.", "name": "0xdnl 🦊", "handle": "0xdnll", "avatar": "https://pbs.twimg.com/profile_images/2095255228333629440/4vyWuchI_200x200.jpg", "likes": 43, "rts": 2, "replies": 25, "views": 282, "ts": 1792557007, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112763092853489664/vid/avc1/1280x720/Uwq5NqMgG0LGLWsU.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112763092853489664/vid/avc1/1920x1080/iqIxOE4n9dbZqNWV.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112763092853489664/img/1SaF8z1oLCGOaxfj.jpg", "dur": 35}], "quote": {"id": "2109987785398472982", "url": "https://x.com/GenLayer/status/2109987785398472982", "text": "When it was just the three of us, Albert knew everyone who touched GenLayer. Now thousands of people build on it. \n\nThe project of our lives became the place where others build theirs.\n\nGenesis, Episode 5.", "name": "GenLayer", "handle": "GenLayer", "avatar": "https://pbs.twimg.com/profile_images/2011221321754034176/AaBmFyfD_200x200.jpg", "likes": 288, "rts": 60, "replies": 35, "views": 181906, "ts": 1791895264, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2109987704033202176/vid/avc1/1280x720/OhLYbBMi-nkPIBad.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2109987704033202176/vid/avc1/1920x1080/UGMkuiJnaWOgqy5e.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2109987704033202176/img/VOSZ7zvJ4wGr2nB4.jpg", "dur": 183}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Tools & Agents", "score": 5.65, "thread": [], "tier": "worth"}, {"id": "2112592370235572352", "url": "https://x.com/undefinedKi/status/2112592370235572352", "text": "A Netflix engineer whose tool already saved users ~$700k in API bills made it free for everyone. It cuts what your agents burn on junk context\n\nIt's called Headroom, by Tejas Chopra. Several teams at Netflix already run it.\n\nWhat it does:\n\n1. Compresses everything your agent reads before it hits the model: logs, tool outputs, JSON, files, chat history\n\n2. About 20% fewer tokens for coding agents and 60-95% fewer on JSON, with the same answers\n\n3. Nothing is lost. Originals stay cached on your machine and the model pulls them back when it needs them\n\n4. \"headroom learn\" mines your failed sessions and writes the fixes into your CLAUDE.md or AGENTS.md\n\n5. Runs locally. No prompt or file leaves your machine to be compressed\n\nOne command: \"headroom wrap claude\" (or codex, cursor, aider). Undo with \"headroom unwrap\"\n\nFree and open source. You can install it today.\n\nRepo: https://github.com/headroomlabs-ai/headroom", "name": "Yarchi", "handle": "undefinedKi", "avatar": "https://pbs.twimg.com/profile_images/2054664188417413120/DZKz0Tqn_200x200.jpg", "likes": 81, "rts": 14, "replies": 22, "views": 4217, "ts": 1792516245, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112592325809422337/vid/avc1/1280x720/hgolGS3juVaMoqRu.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112592325809422337/vid/avc1/1920x1080/AJ4sdf4OByp8QSbJ.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112592325809422337/img/eGlbnROHEXnYWL9A.jpg", "dur": 34}], "quote": {"id": "2104569496564367837", "url": "https://x.com/undefinedKi/status/2104569496564367837", "text": "https://x.com/i/article/2104385200423649280", "name": "Yarchi", "handle": "undefinedKi", "avatar": "https://pbs.twimg.com/profile_images/2054664188417413120/DZKz0Tqn_200x200.jpg", "likes": 395, "rts": 43, "replies": 14, "views": 610671, "ts": 1790603443, "media": [], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.64, "thread": [], "tier": "worth"}, {"id": "2112629213211828652", "url": "https://x.com/JonPTaylor/status/2112629213211828652", "text": "Phonon from @GradiumAI is an open TTS model in 31M and 40M sizes, perfect for on-device! It’s voice promptable too, via Gradium’s Voice Designer.\n\nI love experimenting with voice and mobile. Here is Little Voices, an app where you can ask the angel and devil on your shoulder anything. It's a @pipecat_ai app in embedded Python on iPhone. \n\n• Apple SpeechAnalyzer for speech-to-text\n• Apple Foundation Models for the LLM\n• Gradium Phonon 31M for TTS. \n• Pipecat running in Python on the iPhone\n• Pipecat Audience (for who speaks next. It works out whether you’re talking to the angel or the devil.)\n• No network or inference costs!\n\n📖 Repo here: https://github.com/pipecat-ai/ios-little-voices", "name": "Jon Taylor", "handle": "JonPTaylor", "avatar": "https://pbs.twimg.com/profile_images/1430145467770458126/MAhFg0W7_200x200.jpg", "likes": 105, "rts": 8, "replies": 10, "views": 6514, "ts": 1792525029, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112629031271342080/vid/avc1/1276x720/T9K6JiY_OJFrPpoe.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112629031271342080/vid/avc1/3832x2160/IbFVol_BsapNDfb-.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112629031271342080/img/DtYVbn-K5XHF_gIi.jpg", "dur": 196}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 5.64, "thread": [], "tier": "worth"}, {"id": "2112676336942600376", "url": "https://x.com/Nozelcode/status/2112676336942600376", "text": "Getting AI characters to move naturally is one thing. \nGetting them to move the way you imagined is another. \nDreamina Canvas has motion capture, letting you bring character motion and spatial depth from a reference video into a new scene. Dreamina Basic is just $1.50 for a full month, with credits for up to 9 ten-second Seedance videos.\n\nDreamina 2.0 is canvas-first — the new way AI video is made.\n\n👉https://dreamina.capcut.com/ai-tool/home/?need_login=true&utm_medium=social&utm_source=x&utm_campaign=web2canvas_2\n\n#Dreamina #DreaminaPartner", "name": "roman", "handle": "Nozelcode", "avatar": "https://pbs.twimg.com/profile_images/2073450678727380992/6NTjm6pf_200x200.jpg", "likes": 81, "rts": 5, "replies": 16, "views": 2902, "ts": 1792536265, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112676270702030848/vid/avc1/720x1280/yKpJbjOLPTjhy50c.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112676270702030848/vid/avc1/1080x1920/Ot5HSanegYqDGS7N.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112676270702030848/img/tVGxzf_BFFSpmmhC.jpg", "dur": 11}], "quote": null, "reply_to": null, "cat": "AI Tools & Agents", "score": 5.64, "thread": [], "tier": "worth"}, {"id": "2112645390369718527", "url": "https://x.com/realDonaldTrump/status/2112645390369718527", "text": "🚨 OHIO!\n\nEarly Voting, in-person, is UNDERWAY NOW in the Great State of Ohio. If you have a mail-in ballot, return it immediately and, if not, GO VOTE at the Polls RIGHT NOW, and get everyone you know to VOTE FOR THE REPUBLICAN IN EVERY RACE, UP AND DOWN THE BALLOT!\n\nWhether you VOTE early, absentee, by mail, or in-person, Republicans must SWAMP the Radical Left Dumocrats with massive turnout! In Ohio, you can cast your early Vote, in-person, all the way through November 1st. SO IMPORTANT — PLEASE GET OUT AND VOTE. MAGA! President DONALD J. TRUMP\n\nFind your Voting Location here: https://swampthevoteusa.com/ohio/", "name": "Donald J. Trump", "handle": "realDonaldTrump", "avatar": "https://pbs.twimg.com/profile_images/874276197357596672/kUuht00m_200x200.jpg", "likes": 11546, "rts": 2405, "replies": 1712, "views": 1182724, "ts": 1792528886, "media": [], "quote": null, "reply_to": null, "cat": "Politics & World", "score": 5.64, "thread": [], "tier": "worth"}, {"id": "2112487852156063849", "url": "https://x.com/vib3coded/status/2112487852156063849", "text": "One of these whales has definitely eaten the instructions\n\nGPT-6 Astra vs Claude Opus 5.5 - same prompt, two very different whales\n\nOpus made a cute beluga-whale mix. Astra made a googly-eyed idiot that’s 50% mouth. No thoughts. Just krill 😭\n\nAstra: $9.12\nOpus: $13.60\n\nWhich one are you taking home?", "name": "Vib3Coded", "handle": "vib3coded", "avatar": "https://pbs.twimg.com/profile_images/2093006364729659392/0EAnjDsN_200x200.jpg", "likes": 136, "rts": 14, "replies": 24, "views": 8728, "ts": 1792491326, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112486198539161600/vid/avc1/720x912/5KKw_0vAjxonmr9B.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112486198539161600/vid/avc1/1080x1368/1_Dy4fRn6lGSK_MW.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112486198539161600/img/HZ8cTNlCm7znCBRt.jpg", "dur": 18}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 5.63, "thread": [], "tier": "worth"}, {"id": "2112566784343876081", "url": "https://x.com/_akhaliq/status/2112566784343876081", "text": "OpenVLHarness\n\nReal World Visual Agentic Tool-Use with Multimodal Memory\n\npaper: https://huggingface.co/papers/2610.26860", "name": "AK", "handle": "_akhaliq", "avatar": "https://pbs.twimg.com/profile_images/1451191636810092553/kpM5Fe12_200x200.jpg", "likes": 108, "rts": 15, "replies": 11, "views": 13158, "ts": 1792510145, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112566699740237824/vid/avc1/1280x720/czUlEhsd2qkaDnUo.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112566699740237824/vid/avc1/1920x1080/z7ZrLQRJYfe5_PDa.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112566699740237824/img/xcxH6yQaEClcBRjJ.jpg", "dur": 110}], "quote": null, "reply_to": null, "cat": "AI Tools & Agents", "score": 5.63, "thread": [], "tier": "worth"}, {"id": "2112624102016249952", "url": "https://x.com/runinfrai/status/2112624102016249952", "text": "runinfra coding plan is live\n\nthe fastest open models in claude code, codex, opencode and 16 more agents. from $10 a month\n\nmore usage per dollar and faster tok/s than other providers. both, not one or the other\n\nDeepSeek V4.1 Flash, GLM 5.3, Ornith 1.5 122B, Qwen3.8 27B and more. one sub\n\nup to 378 tok/s. up to 99.3% cache hit. cached input from $0.01 / 1M, so the plan goes further\n\n$10 → ~$12 of usage\n$29 → ~$35\n$99 → ~$119\n\nlimits reset every 5 hours and every week. hit one and you pick: credits, or free standby. never a dead stop mid-task\n\nsetup is one prompt -- paste it into your agent and it wires itself\n\nhttps://runinfra.ai/pricing?plan=coding", "name": "RunInfra (YC F26)", "handle": "runinfrai", "avatar": "https://pbs.twimg.com/profile_images/2103573892392783872/8R_YGdP3_200x200.jpg", "likes": 83, "rts": 11, "replies": 16, "views": 9178, "ts": 1792523811, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112622250721787904/vid/avc1/1280x720/biU3hqWfrqDCMDVh.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112622250721787904/vid/avc1/1920x1080/5z69mDlkMAnUhTR-.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112622250721787904/img/QZjqfO9SIl4vCNXx.jpg", "dur": 37}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 5.63, "thread": [], "tier": "worth"}, {"id": "2112618019205870068", "url": "https://x.com/Breaking911/status/2112618019205870068", "text": "BREAKING: President Trump announced a anti-fraud program that would pay people who expose fraud 1% of the money recovered. “If you find $1 billion, we are giving a commission to that person of 1%,” he said.", "name": "Breaking911", "handle": "Breaking911", "avatar": "https://pbs.twimg.com/profile_images/619546088995979264/KuG27bBK_200x200.jpg", "likes": 16430, "rts": 1723, "replies": 1070, "views": 1020768, "ts": 1792522360, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112617986196475904/vid/avc1/640x360/vlT-C2cuM2dMxZNc.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112617986196475904/vid/avc1/1280x720/7ky4ryO_eCURpikM.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112617986196475904/img/a8NWZJOn25IujPdx.jpg", "dur": 33}], "quote": null, "reply_to": null, "cat": "Politics & World", "score": 5.63, "thread": [], "tier": "worth"}, {"id": "2112578703498912108", "url": "https://x.com/marcusyul/status/2112578703498912108", "text": "NADIE ESTÁ HABLANDO DE ESTO Y ES DE LO MÁS FUERTE DEL AÑO\n\nUn laboratorio independiente acaba de meterse en el top 5 mundial de edición de imagen.\n\nRanking de Artificial Analysis:\n\n→ 3º Google, 1152\n→ 4º Krea 3 Ultra, 1151\n→ 5º Microsoft, 1151\n\nArriba solo hay gigantes.\n\nOpenAI va a valer más de 1,4 billones.\nMeta gasta hasta 135.000 millones este año.\n\nKrea ha levantado 80 millones en toda su historia.\n\nY está a un punto de Google.", "name": "marcus", "handle": "marcusyul", "avatar": "https://pbs.twimg.com/profile_images/2111849261096718336/9rC8a9xw_200x200.jpg", "likes": 100, "rts": 17, "replies": 10, "views": 21051, "ts": 1792512987, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112578678060400640/vid/avc1/1280x720/2zXNPExnWD1EB7ks.mp4?tag=16", "hd": "https://video.twimg.com/amplify_video/2112578678060400640/vid/avc1/1920x1080/S9EEDg3T6NF1TKTF.mp4?tag=16", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112578678060400640/img/bDyyMKPSnBsfgANy.jpg", "dur": 7}], "quote": {"id": "2112567020353102324", "url": "https://x.com/krea_ai/status/2112567020353102324", "text": "today, Krea 3 makes it to the top of image arenas.\n\n- \"Fast\" pushes the pareto curve of speed and quality.\n- \"Ultra\" ranks top-4, only surpassed by OpenAI models.\n\nthe only company valued under $1T in the top-10!\n\nmore below 👇", "name": "Krea", "handle": "krea_ai", "avatar": "https://pbs.twimg.com/profile_images/2052148578588753920/deUXA7cZ_200x200.jpg", "likes": 1098, "rts": 143, "replies": 103, "views": 911816, "ts": 1792510201, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112560706319261696/vid/avc1/1280x720/I09XfdJSlPHN1GRN.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112560706319261696/vid/avc1/1920x1080/dNLTktxkBQvdw6CQ.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112560706319261696/img/adh7bZDj88TDFAP8.jpg", "dur": 35}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.63, "thread": [], "tier": "worth"}, {"id": "2112557189885993395", "url": "https://x.com/myogiadityanath/status/2112557189885993395", "text": "दुनिया के अंदर मुसलमान-मुसलमान आपस में लड़ रहे हैं...\nकम्युनिस्ट-कम्युनिस्ट लड़ रहे हैं,\nक्रिश्चियन-क्रिश्चियन लड़ रहे हैं...\n\nअकेले भारत सनातन की छाया में हर जाति, हर संप्रदाय, हर मत, हर मजहब को सुरक्षा भी दे रहा है, उसको समृद्धि के पथ पर भी बिना भेदभाव के अग्रसर कर रहा है...", "name": "Yogi Adityanath", "handle": "myogiadityanath", "avatar": "https://pbs.twimg.com/profile_images/2054826013042020352/Hs7YxXuJ_200x200.jpg", "likes": 17754, "rts": 3272, "replies": 680, "views": 365446, "ts": 1792507858, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112556785026691072/vid/avc1/1280x720/Os4I5xO1JiDoTl9e.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112556785026691072/vid/avc1/1920x1080/nH0eQUoY3-0_MOQx.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112556785026691072/img/8x1cD_2DibrJ-WTm.jpg", "dur": 150}], "quote": null, "reply_to": null, "cat": "Everything Else", "score": 5.63, "thread": [], "tier": "worth"}, {"id": "2112465125722751457", "url": "https://x.com/cyrilXBT/status/2112465125722751457", "text": "POV: you show a Grok Bot how you do something ONCE\n\n\"Got it. Here are the 9 steps you took.\"\n\n\"Step 4 looked like a judgment call. Why did you pick that option?\"\n\n\"Steps 7 and 9 send emails. I'll ask before doing those.\"\n\n\"Saved as a routine. Say 'run onboarding' anytime.\"\n\nNo prompt writing.\n\nYou just did the job once while it watched.\n\nHow to set it up", "name": "CyrilXBT", "handle": "cyrilXBT", "avatar": "https://pbs.twimg.com/profile_images/2035229727414534145/aWap3Jbq_200x200.jpg", "likes": 146, "rts": 20, "replies": 16, "views": 12503, "ts": 1792485908, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112465093984432128/vid/avc1/720x900/5rWAwU3DxiUNcpq4.mp4?tag=16", "hd": "https://video.twimg.com/amplify_video/2112465093984432128/vid/avc1/1080x1350/j5_OW9FMy3-i3Q0u.mp4?tag=16", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112465093984432128/img/PuJpFLTkb-2728bA.jpg", "dur": 30}], "quote": {"id": "2112006867022958931", "url": "https://x.com/cyrilXBT/status/2112006867022958931", "text": "https://x.com/i/article/2111965832683089920", "name": "CyrilXBT", "handle": "cyrilXBT", "avatar": "https://pbs.twimg.com/profile_images/2035229727414534145/aWap3Jbq_200x200.jpg", "likes": 162, "rts": 14, "replies": 22, "views": 110277, "ts": 1792376650, "media": [], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.62, "thread": [], "tier": "worth"}, {"id": "2112727316216549667", "url": "https://x.com/ai_for_success/status/2112727316216549667", "text": "Grok Bot team, a reset would be greatly appreciated 😊\n\nI don't think I'm going to make it through today and the next 4 days without Grok bot.", "name": "AshutoshShrivastava", "handle": "ai_for_success", "avatar": "https://pbs.twimg.com/profile_images/1687401026805256192/uQ1o2wVQ_200x200.jpg", "likes": 68, "rts": 2, "replies": 15, "views": 3574, "ts": 1792548419, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVHqRwkbIAAdJf8.jpg?name=orig"}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 5.62, "thread": [], "tier": "worth"}, {"id": "2112573025736601842", "url": "https://x.com/marktenenholtz/status/2112573025736601842", "text": "Local inference is the future, so we made local Perplexity. Enjoy!", "name": "Mark Tenenholtz", "handle": "marktenenholtz", "avatar": "https://pbs.twimg.com/profile_images/1468741945560289283/YZ3cOr_H_200x200.jpg", "likes": 134, "rts": 4, "replies": 11, "views": 10136, "ts": 1792511633, "media": [], "quote": {"id": "2112571597798461920", "url": "https://x.com/perplexity_ai/status/2112571597798461920", "text": "Perplexity Computer can now run fully local on your Mac.\n\nWork with your native Mac apps and local files, and run tasks without sending sensitive data to the cloud. The model and the agent both run on your Mac.\n\nAvailable now in the Perplexity Mac app.", "name": "Perplexity", "handle": "perplexity_ai", "avatar": "https://pbs.twimg.com/profile_images/2009310641165660160/XArF3_Ib_200x200.jpg", "likes": 1424, "rts": 128, "replies": 132, "views": 225211, "ts": 1792511293, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112571479745495040/vid/avc1/1280x720/ShXKzcJ5aZU2oEqH.mp4?tag=16", "hd": "https://video.twimg.com/amplify_video/2112571479745495040/vid/avc1/1920x1080/-Cm77YMLPTK8ejoZ.mp4?tag=16", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112571479745495040/img/6agUzZjpfbZMBBOA.jpg", "dur": 69}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.62, "thread": [], "tier": "worth"}, {"id": "2112553458330976585", "url": "https://x.com/Scobleizer/status/2112553458330976585", "text": "Every time you switch from Claude Code to Codex because you ran out of tokens, you start over and explain your whole project again.\n\nBeacon is trying to fix that. \n\nIt saves your sessions across Claude Code, Cursor, Codex and 20+ other tools, so one command hands the work to the next agent with everything it learned. \n\nIt's open source, and they just raised $5.5M.\n\nYour fixes and debugging habits stay with you instead of getting locked inside one company's tool.\n\nHow many times this week did you re-explain the same project to a different AI?\n\nhttps://github.com/Asymptote-Labs/agent-beacon", "name": "Robert Scoble", "handle": "Scobleizer", "avatar": "https://pbs.twimg.com/profile_images/1915614118876504066/zVnfpAMf_200x200.jpg", "likes": 82, "rts": 7, "replies": 37, "views": 11382, "ts": 1792506968, "media": [], "quote": {"id": "2112552451547001218", "url": "https://x.com/jqdsouza/status/2112552451547001218", "text": "We’re betting our $5.5M seed round that the next leap in AI coding won’t come from OpenAI or Anthropic.\n\nIt’ll come from a new feedback loop that learns from you.\n\nIntroducing Beacon: open-source, self-improving memory for coding agents.\n\nYour sessions capture how you debug and solve problems. Today, that context gets lost and you have to re-explain things every time you switch tools.\n\nBeacon continuously distills your sessions into reusable skills across Claude Code, Cursor, Codex, and 20+ harnesses, so your next agent can learn from the last.\n\nBeacon is free and OSS 🌟 http://github.com/Asymptote-Labs/agent-beacon\n\nWhy should the frontier labs be the only ones winning with your sessions?\n\nYou already did the work. Now let your coding agents learn from you.", "name": "Justin D'Souza", "handle": "jqdsouza", "avatar": "https://pbs.twimg.com/profile_images/1817440734766604288/99FuIxoo_200x200.jpg", "likes": 1279, "rts": 141, "replies": 251, "views": 425836, "ts": 1792506728, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112552129952874496/vid/avc1/1280x720/mhJ2imMl6mA4kQEF.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112552129952874496/vid/avc1/1920x1080/2nvostHi1eUMqE7-.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112552129952874496/img/X1ifILIq6yhlSaGJ.jpg", "dur": 109}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.61, "thread": [], "tier": "worth"}, {"id": "2112616656723747214", "url": "https://x.com/vincentweisser/status/2112616656723747214", "text": "Open Superintelligence Research Day\n\nFriday, October 23\nBerlin\n\nhttps://luma.com/primeintellect-berlin", "name": "Vincent Weisser", "handle": "vincentweisser", "avatar": "https://pbs.twimg.com/profile_images/2027646480438194176/hM1tWDkF_200x200.jpg", "likes": 101, "rts": 9, "replies": 8, "views": 3095, "ts": 1792522036, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112585440482185216/vid/avc1/1280x720/Bo1rAmay0jVTibTV.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112585440482185216/vid/avc1/1920x1080/y5GRvuhkTgpAQlpm.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112585440482185216/img/bApf0bUbaw3Nqilb.jpg", "dur": 28}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 5.61, "thread": [], "tier": "worth"}, {"id": "2112699939310694640", "url": "https://x.com/mycoin68/status/2112699939310694640", "text": "The strongest trees grow in the windiest places, and the strongest people are often those who have faced the most storms yet still choose to stand tall.", "name": "Crypto.Eth", "handle": "mycoin68", "avatar": "https://pbs.twimg.com/profile_images/1977632531794345984/ifJ_-sEN_200x200.jpg", "likes": 37, "rts": 0, "replies": 36, "views": 318, "ts": 1792541892, "media": [], "quote": {"id": "2112695611141017673", "url": "https://x.com/elenalin01/status/2112695611141017673", "text": "@zerufinance just shipped the API that decides who deserves the airdrop.\n\nNew Oct 20 12:31 post: \"Better token allocation starts with better wallet intelligence. ZeruAI's Allocation API helps protocols improve airdrops, token launches, and incentive programs.\" 13.2K views. Image: \"Smarter airdrops and incentives.\"\n\nThree signals: (1) Sybil resistance — farmed wallets identified via account age, funding patterns, activity consistency, cross-protocol history. (2) Wallet quality ranking — rank eligible wallets by score band and protocol category, prioritize users who actively use your protocol. (3) Dumping-risk signals — token-level conviction + past exit behavior: who holds through volatility, who sells on day one.\n\nBuilt for pre-TGE projects, L1/L2 ecosystems, launchpads, foundations, incentive programs. Link card: \"Enterprise APIs | Trust Signal APIs for Wallets.\"\nThe other engine still runs: news-feed post now 17K views; Aspen LIVE now 48.5K; pinned competition now 52.5K; 66.1K followers; trust oracles powering Zaps; zScore live on @etherscan; http://zeruai.org.\n\nMost airdrops spray and pray. Zeru's allocation aims — at the wallets that actually use your protocol. Smarter airdrops and incentives. The farmers just got filtered.", "name": "Bon.ETH", "handle": "elenalin01", "avatar": "https://pbs.twimg.com/profile_images/2108931044145856512/pD4eAF0r_200x200.jpg", "likes": 46, "rts": 23, "replies": 50, "views": 4464, "ts": 1792540860, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112690887046385664/vid/avc1/1280x720/yrewrVfG1R5PjDh0.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112690887046385664/vid/avc1/1920x1080/vh0eHTbMMwSDWKRS.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112690887046385664/img/pnzM-OVBax-KaiRX.jpg", "dur": 10}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Tools & Agents", "score": 5.61, "thread": [], "tier": "worth"}, {"id": "2112751346948411683", "url": "https://x.com/David_Kasten/status/2112751346948411683", "text": "You describe a major policy rollout that would affect US law nationwide, and preempt the laws of the state you're resident in, as merely \"rhetoric or policy communication that wasn’t carefully written or resulting from fast-changing circumstances not propagating from one team to another fast enough.\"\n\nI doubt that framing and diagnosis of root causes.  But let's grant it the sake of argument.\n\nWhat are you doing therefore to ensure that your government affairs team learns how to pay attention to, and get in sync with, the concerns of Anthropic technical staff broadly?  Where is your blameless postmortem to prevent this failure from happening again on matters of national security policy consequence?", "name": "dave kasten", "handle": "David_Kasten", "avatar": "https://pbs.twimg.com/profile_images/1589811166670381057/Hckp4GJt_200x200.jpg", "likes": 74, "rts": 6, "replies": 1, "views": 7372, "ts": 1792554148, "media": [], "quote": null, "reply_to": "2112732230124818891", "cat": "AI Models & Labs", "score": 5.61, "thread": [{"id": "2112732230124818891", "url": "https://x.com/DarioAmodei/status/2112732230124818891", "text": "Thank you for this, @_NathanCalvin. I appreciate and am a fan of the investigative work you’ve done on behalf of AI safety and believe your comments are coming from a constructive, honest place, and that it benefits the public to have people whose job is to scrutinize the actions of frontier AI companies. I think something would be wrong if companies of the size of Anthropic didn’t get harshly criticized basically every day; strong antibodies against corporate power are a healthy feature of a free society, and especially so when issues of the gravity of the one we’re facing are at play. I also do agree that some of the examples you cite were mistakes by Anthropic.\n\nThat said, I disagree with the thrust of your post. At the core, a good fraction of the things you criticize are consequences of Anthropic’s basic theory of change that we have held for many years. Our strategy has always been what I’ve called the “race to the top” — by showing how it’s possible to build the technology responsibly, we can raise the bar for the entire industry. The forces that drive the race to the top are hugely more effective if the company practicing them is at the frontier; that’s one lesson I’ve learned repeatedly. And looking at that strategy as a whole, I’m proud of our track record and stand by it.\n\nI believe that if we take a list of things that Anthropic did in the past year that were pro-safety and commercially costly to us, they far outweigh the list you’ve made, while at the same time I also disagree with some of the items on your list. Here are some things Anthropic has done, in the same period you’ve cited (the last year), which were very costly to us commercially while having strong safety benefits:\n\n1. We played a key role in SB53 (and other state laws), at a time when doing so was politically perilous to the company and AI regulation was very unpopular. We in fact argued for a stronger version of SB53 than was ultimately passed; there were a lot of stakeholders and we were not the limiting factor in the strength of the bill that was passed.\n\n2. We have very strong biological safeguards on our models, because we’ve seen concerning results in bio uplift trials and even seen and blocked potential attempts to misuse our models for bioweapons (as seen in our threat intelligence report from a few weeks ago). This is a very serious threat that we want to have zero tolerance for. But having very low false negatives means having significant false positives (despite months of effort on our part to improve the classifiers), enough so that biologists joke about how restrictive our classifiers are, and competitors sometimes sell against us by touting their more permissive bio capabilities. This has been very painful to us in an area where we care a lot about supporting an ecosystem of Claude users (biomedical science; and it is particularly frustrating to me as a biologist), but it’s the right thing to do and we intend to keep doing it.\n\n3. Similarly, we first had Mythos-class models in February but didn’t make them generally available until June (when we had stronger cyber safeguards in place). We only offered them to a limited set of partners in order to focus on cyberdefense. It would have been much more economically rational to simply release the model to everyone. We likely sacrificed a significant chunk of a several-month model lead. But because of this, many companies secured their cyber infrastructure before the deluge of widely available cyber-capable models. Of course there are ways it could have gone better or been run better, but this was what we were aiming to do.\n\n4. I advocated forcefully and publicly, in my essay Policy on the AI Exponential in June of this year, for the government to have the power to block model releases. Back then this was still outside or maybe on the edge of the Overton window, though I understand the window has moved since then. We were attacked intensely for this.\n\n5. I don’t want to re-ignite conflict, but the events of February 2026 are a strong example. It is clear that our public stance could have seriously damaged the company’s future.\n\n6. We’ve continued to advocate for export controls on chips and chipmaking equipment to China, because we think it allows democracies to negotiate from a position of strength on AI safety agreements. We’ve done this despite problems it’s created for us with industry partners who hold very different views and on whom we are very dependent.\n\n7. As far as I’m aware we were the first, and still only, frontier company to restrict the sale of AI services to PRC-controlled companies, including those operating through third countries (otherwise a major loophole). We’ve therefore forfeited significant short-term business to prevent fueling AI platforms and applications that would help the CCP’s military and intelligence services. We are also cracking down on distillation; generally, distillation is not a major threat to us commercially, but like chip exports it has concerning national security and safety implications, so we expend significant energy and company resources to address it.\n\n8. As you mentioned, we’ve put out a lot of reports, announcements, long model cards, public advocacy, etc, all trying to inform the public about the risks of AI. These involve a level of detail and effort that would be implausible for a purely profit-maximizing company.\n\n9. Just this week, we announced we were putting 5% (and possibly more over time) of the company into a public benefit fund.\n\nAll of these decisions came with very substantial costs to us. To be fair, those that involved holding back or restricting access to frontier capabilities also had a broader cost — for example, the public might otherwise have benefitted from faster progress in biology, so I am not saying that our decisions were without tradeoffs — but they were not driven by profit-seeking.\n\nFor each decision, you can come up with ulterior motives that could have driven us — I think it is a general truth that any decision, on any topic, can always be portrayed as a nefarious scheme. But most of those end up being pretty farfetched or don’t fully make sense if you actually examine them closely. For example, it is deeply implausible that it would be a shrewd business move to block a large swath of research biology in order to do the work ourselves and compete with our customers; we expect the benefit to the ecosystem to greatly exceed the work Anthropic does itself, and for the two to complement each other. It is not in Anthropic’s interest to be perceived as unfriendly to biologists. Our Life Sciences Verification Program, which gives vetted biology professionals access to our models, also refutes this idea. \n\nOf course, a different set of people will see this and make a different criticism: that Anthropic shouldn't be making decisions about who gets access to what in the first place. I agree, in the sense that ideally the government would be making these decisions, and that’s why we advocate for regulation. But for now we are forced to make them, and enabling bioterrorism isn’t a better option.\n\nI think that even if I conceded every item in your list, I would happily hold up mine next to it; I don’t think it’s a close call. That is of course partly subjective and different things are important to different people. Maybe one way you could object is that several of the items above relate to AI misuse and not loss-of-control; if you think the latter is much more important than the former, that might change your calculus. But this is not Anthropic’s view — we view both as serious issues. You can also disagree with our decisions, as many have, but they are consistent.\n\nBut I also disagree with at least some of your list. Several items don’t represent a deviation from Anthropic’s strategy or values at all, once we postulate the “race to the top” strategy that requires being a frontier AI company. Your items 1-4 are all simply examples of what it means to compete at the frontier, and we stand by them, both in the sense that they are transparently ordinary things to do as part of that strategy, and that we stand by the strategy as a whole. \n\nTo be fair, there are important questions worth confronting (and that we are confronting) about what to do when the AI-driven acceleration gets fast enough that it is hard for safety to keep up. We are nearing that point and that’s what’s driving some of our thinking about “pacing.” But 1-4 are actions taken before that point and should be perfectly expected based on Anthropic’s strategy as a company. Of course it is possible to disagree with that strategy, but that’s a more fundamental disagreement that you could have had any time over the last few years.\n\nI agree we could have handled your items 7, 8, and 9 better. All fall into the category of “rhetoric or policy communication that wasn’t carefully written or resulting from fast-changing circumstances not propagating from one team to another fast enough.” This kind of thing happens a lot in large organizations (Anthropic is over 5,000 people), and doesn’t even necessarily represent a failure or mistake of any single person. I am of course the CEO, and I take responsibility. The volume of communication from Anthropic is enormous and if these are the worst examples, I think we’re frankly doing pretty well, though I will continue to work hard to make sure we do even better.\n\nYour 5th item (the change to our RSP) is the most substantive item, and people can debate this, but I think that the old, more rigid RSP created a lot of situations where we were technically required to do something that required a lot of effort but in retrospect wasn’t very important for safety, as well as not covering some of the most important things. Our current RSP’s focus on transparency brought things like risk reports and roadmaps, and its emphasis on independent external review laid the groundwork for even more intensive embedded evaluation, all of which I think have been valuable in driving a race to the top. In the original announcement in September 2023, we described the RSP as an “early iteration that we [would] build on” and said that “rapid iteration…will almost certainly be necessary.” I understand that changing plans is always a move that creates justifiable scrutiny — I just don’t think we ever represented that we wouldn’t do so.\n\nRelating to your 6th item (having an FCF in addition to our RSP), I know our intent is to meet the letter and spirit of our regulatory obligations (via our FCF) while also remaining able to experiment with more novel approaches to risk management that go beyond what the law currently requires (via our RSP). I promise to look into it further, as it’s a complex issue and it is possible we are not weighing the considerations in the right way.\n\nOverall, although Anthropic has made plenty of mistakes as an organization — including some of the items on your list — I feel that we have repeatedly taken serious and substantive actions counter to our bottom line and that there is a significant negativity bias distorting assessments like the one you are making above. We’ll always try to do better but, again, I am extremely proud of our track record and stand by it. I will have more to say soon about how we are going to further live our values in this moment of rapid change.", "name": "Dario Amodei", "handle": "DarioAmodei", "avatar": "https://pbs.twimg.com/profile_images/2015835742577012736/uOwdzrEz_200x200.jpg", "likes": 1884, "rts": 144, "replies": 262, "views": 264787, "ts": 1792549590, "media": [], "quote": {"id": "2112295219765137570", "url": "https://x.com/_NathanCalvin/status/2112295219765137570", "text": "Thank you for taking the time to respond thoroughly on a weekend. I realize that drafting legislation is difficult and some degree of iteration and response to feedback is inevitable and appropriate.\n\nHowever, I feel like your response is still not really engaging with the heart of my concern about Anthropic's behavior here, and it makes me think that these sorts of problems and tendencies  will only resurface moving forward. I also think that now might be a good time to take a broader step back as to where we find ourselves and how Anthropic sees its role, and how external folks who care about AI safety like myself increasingly see Anthropic.\n\n(Fair warning: this response is a bit long)\n\nTo explain what I mean (and at the risk of being a bit esoteric), it’s worth asking the question: what is Anthropic? How do its leaders and employees think of Anthropic’s role? Is that conception matched by how it actually behaves and impacts the world?\n\nOne answer is an extremely large tech company that exists to make its employees and investors mind-bogglingly wealthy. Anthropic is sometimes described as a startup, but if Anthropic successfully IPOs at 2 trillion dollars (a number it has been reportedly targeting), it would be more valuable than Meta - which is worth 1.8 trillion.\n\nAnother answer is an AI safety organization, whose core values are those of the sort laid out in the 2023 essay from Anthropic’s co-founders entitled “Core views on AI safety: When, why, what, and how.” In that essay they said that if we were in a world where alignment was hard (and that without strong evidence to the contrary, we should assume this is the scenario we are in):\n\n “Anthropic’s role will be to provide as much evidence as possible that AI safety techniques cannot prevent serious or catastrophic safety risks from advanced AI, and to sound the alarm so that the world’s institutions can channel collective effort towards preventing the development of dangerous AIs. If we’re in a “near-pessimistic” scenario, this could instead involve channeling our collective efforts towards AI safety research and halting AI progress in the meantime. Indications that we are in a pessimistic or near-pessimistic scenario may be sudden and hard to spot. We should therefore always act under the assumption that we still may be in such a scenario unless we have sufficient evidence that we are not.”\n\nThere have been more recent articulations of this version of Anthropic, for instance in Dario’s recent essay warning: \n\n“We must slow the pace at which we improve the capabilities of AI models… it’s my worry that in 6–12 months such a swarm could be capable of taking over the entire internet with a persistent botnet…  incidents have happened across the industry, including at Anthropic, and I believe it’s incumbent on every frontier AI company to act as if OAI-HF had happened to them… more intelligent models are more capable of deceiving tests, and thus may appear aligned while having serious problems that go undetected…”\n\nA third view is that Anthropic exists not as a normal profit motivated company, or an AI safety organization seeking to help raise the alarm and solve collective action problems associated with AI development, but instead as an organization primarily concerned with creating superhuman AI capabilities before anyone else, in particular through creating a process whereby the current generation of Anthropic’s AI systems can autonomously build their successors, and those successors build their successors, and so on. \n\nThe motivations for wanting to win this race may be manifold - maybe for the pure profit of Answer 1, but perhaps also because Anthropic believes that the best way to make the world better is for them to win this race instead of their more reckless colleagues; or, because of normal human pride and ambition. But the results (and risks, which Anthropic claims existentially threaten every single human being on earth) are the same.\n\nAnthropic employees and leaders may seek to answer this question on what Anthropic is by introspecting on their own intentions and those of their colleagues. But those of us outside the organization have more limited tools available to us - we can only see what Anthropic and its employees say and do, not how it feels or looks on the inside.\n\nWhen I look at many notable actions that Anthropic has taken over the past year, that evidence seems most consistent to me with the view that Anthropic is primarily trying to win the race to super intelligence, and that other considerations (including safety) are fundamentally secondary. These actions include: \n\n1. Announced plans to build an in-house custom silicon chip team to accelerate the inference speeds that Claude operates at.\n\n2. Inked deals for more than $500 billion in compute (according to the Information) to further accelerate AI development.\n\n3. Increased the percentage of AI development tasks that Claude “leads” from 0% in March of this year to 26% August (what is it in October?)\n\n4. Spent a massive percent of compute on internal AI R&D to accelerate development, including use of internal models far better than are available to the public.\n\n5. Switched to Responsible Scaling Policy V3, which abandons its unilateral commitments to slow or stop development if Anthropic is unable to provide sufficient risk assurance.\n\n6. Was the first company to create an alternative weaker “frontier compliance framework” to supplement its RSP, which contains no binding provisions whatsoever on internal deployments.\n\n7. Wrote a letter to Congress (that it later walked back) saying that incidents where Claude was hacking random people were “best understood as a consequence of the misconfiguration, rather than evidence of misaligned goals.”\n\n8. Commented “you can’t do safety from second place,” after the WH SI Accords.\n\n9. Shared a draft bill to Congress that would preempt significant parts of state law (including with language that appears intended to prevent states from blocking dangerous AI deployments), and replace it with federal rules that (despite also containing good provisions) seems to create an enormously high bar for the executive branch to block development or deployment of Anthropic or another AI companies systems.\n\nOf course, this is a deliberately one sided list. Anthropic also published important AI safety research, advanced novel collaborations with third party AI safety organizations, and forcefully spoke out on the importance of AI safety in many public fora (or in private , where I realize a lot of the most valuable work is done and may not be visible to me or those outside the organization).\n\nBut I think it’s worth sitting with how the above list looks to someone outside the company. The sense I have is that for those within the company, many of the items above are treated as anomalies or mistakes that don’t reflect who Anthropic really is. But I have every confidence that if employees at Anthropic saw one of their competitors (e.g. at OpenAI) take some of these actions, they would take it as confirmation of all their worst suspicions. (They might even call OpenAI employees a little gullible for accepting their leadership’s explanations for this behavior at face value.) \n\nPerhaps these were mistakes in the sense that they are not decisions that Anthropic leadership would endorse, but the actions still happened because of incentives and decisions that Anthropic leadership is ultimately responsible for (and would not accept similar excuses from another organization).\n\nWhen Anthropic strays and makes mistakes, why do the mistakes systematically tend to guard and favor Anthropic’s interests? For every provision that was too weak or a giveaway to AI companies in this legislation, why wasn’t there a mistake pushing in the direction of being too strong?\n\nA core part of Anthropic’s theory of change is that being at the frontier gives you more leverage to advocate for stricter policy. I think that conceptually makes sense, but in practice I’ve seen Anthropic push the frontier without substantially pushing the ‘safety frontier’ a remotely equivalent amount.\n\nI want to end by quoting from Anthropic co-founder Chris Olah’s comments around the Magnifica Humanitas release:\n\n“Every frontier AI lab—including Anthropic—operates inside a set of incentives and constraints that can sometimes conflict with doing the right thing. The pressure to stay commercially viable and to stay at the research frontier. Geopolitical pressure. And the older, plainer pressures of pride and ambition. No matter how sincerely any of us intend to do the right thing—and I believe many of us do—we will always be influenced by those incentives.\n\nThat is why, if we want this technology to go well, it is enormously important that there be people outside those incentives—people who care about things going well and insist on safety, who are paying close attention, who are willing to say hard things, who are willing to be our earnest, thoughtful critics.”\n\nI hope these remarks are taken in that constructive spirit, and not as an attack on anyone specific at the organization (certainly not you Anthony, who I have only personally seen act professionally and thoughtfully, and who only ended up getting this diatribe in your replies for random contingent reasons).", "name": "Nathan Calvin", "handle": "_NathanCalvin", "avatar": "https://pbs.twimg.com/profile_images/1976484090426634240/YFgYic9h_200x200.jpg", "likes": 1098, "rts": 110, "replies": 25, "views": 276308, "ts": 1792445399, "media": [], "quote": null, "reply_to": "2111932795714977941"}, "reply_to": null}], "tier": "worth"}, {"id": "2112474799788167647", "url": "https://x.com/ScottyBeamIO/status/2112474799788167647", "text": "IT IS BECOMING F*CKING DANGEROUS. A 23-YEAR-OLD DEV FROM CHINA JUST RAN 300 GROK BOT RESEARCH AGENTS AT THE SAME TIME.\n\nANY TOPIC. RESEARCHED IN MINUTES. AND NONE OF THEM CAN LIE TO HIM.\n\nThese aren’t chatbots. Every single one is a research bot: it finds sources, pulls the facts and writes them up on any topic you give it.\n\nHe opens the live dashboard and it’s a rainbow of bots flying up the screen:\n\n→ 300 Grok Bot research agents digging through sources at the same time\n→ Every claim checked against the original source in ~100 ms\n→ Three passes over 100 company profiles → zero errors left\n→ Everything exported straight into a clean, structured database\n\nThe trick is the split.\n\nSome of the bots do the research. The rest constantly check their work: they confirm every fact and decide whether it’s actually true. If they can’t find a confirmation or a source, they send the task back.\n\nThe loop doesn’t stop until every fact checks out.\n\nThat’s the part most people miss. More agents don’t make research better. A layer that refuses to accept unverified answers does.\n\nMarkets, competitors, people, products, science. Ultra-fast, accurate research on anything, without the usual AI guesswork.\n\nAn analyst team would bill weeks for this. He got it in one run, while the bots kept working on a cloud computer.\n\nWe’re moving from “ask AI a question” to “send a research swarm and only keep what’s proven.”\n\nI broke down the latest major Grok Bot updates and more ways to use them in my article below.\n\nBookmark this and read the full breakdown ↓", "name": "SCOTTY BEAM", "handle": "ScottyBeamIO", "avatar": "https://pbs.twimg.com/profile_images/2029514153656721409/27fG1cCf_200x200.jpg", "likes": 139, "rts": 12, "replies": 22, "views": 7462, "ts": 1792488214, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112474632259330048/vid/avc1/720x900/pxmaaIAEvR3y4JfK.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112474632259330048/vid/avc1/1080x1350/4LF8oF9iTX9aljwS.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112474632259330048/img/pW3vy7bfSqZ2WYw1.jpg", "dur": 15}], "quote": {"id": "2108258293005316298", "url": "https://x.com/ScottyBeamIO/status/2108258293005316298", "text": "Grok Bot just got a MASSIVE upgrade – starting at $20/month.\n\nIt's own email. Smarter agents. Better coding tools. Tasks straight from X.\n\nSet it up once. Give it a goal. Let it keep working while you sleep. https://x.com/i/article/2108171813201080320", "name": "SCOTTY BEAM", "handle": "ScottyBeamIO", "avatar": "https://pbs.twimg.com/profile_images/2029514153656721409/27fG1cCf_200x200.jpg", "likes": 227, "rts": 21, "replies": 21, "views": 133965, "ts": 1791482921, "media": [], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.6, "thread": [], "tier": "worth"}]);